raw:
{
  "candidates": [
    {
      "claimType": "role",
      "statement": "该用户是猫粮的购买者，且家中饲养至少一只猫。",
      "supportingRefs": [
        "finance:商户『猫粮』"
      ],
      "alternativeExplanations": [
        "用户为亲友或室友代购（proxy），本人并非实际饲养者。",
        "用户从事宠物相关行业（如零售、批发）而非个人消费。"
      ],
      "verificationPlan": [
        {
          "op": "checkOwnership",
          "question": "查询是否有其他家庭成员或关联账户也购买了同类商品，以判断是否为共同饲养或代购。"
        },
        {
          "op": "searchCounterEvidence",
          "question": "检查是否有宠物保险、宠物医院就诊记录或宠物用品（如猫砂、玩具）的购买记录来佐证饲养行为。"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现高频购买其他宠物品类或存在明确的家庭成员关联购买，则可能修正为“家庭共同饲养”或“代购角色”。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "conditionalAssociation",
      "statement": "该用户购买的猫粮可能与特定的饮食需求（如低敏/处方粮）相关，尽管过敏记录显示为阴性或极少。",
      "supportingRefs": [
        "finance:商户『猫粮』",
        "health:指标：过敏记录"
      ],
      "alternativeExplanations": [
        "用户购买的只是普通猫粮，过敏记录少是因为从未进行过相关检测或无需关注。",
        "猫粮品牌本身主打天然无添加，用户出于预防性健康理念选择，而非针对现有过敏症状。"
      ],
      "verificationPlan": [
        {
          "op": "retrieveRelated",
          "question": "检索具体购买的猫粮品牌及SKU详情，分析其是否属于特殊功能粮（如肠胃敏感、泌尿道护理等）。"
        },
        {
          "op": "compareConditions",
          "question": "对比购买频率与过敏记录的时序关系，看是否在出现轻微不适后增加了特定类型猫粮的购买。"
        }
      ],
      "whatWouldChangeTheAnswer": "若确认购买的是处方粮或特殊配方粮，则该关联成立；若仅为普通粮，则该假设不成立。",
      "evidenceGrade": "线索",
      "action": "ask"
    }
  ]
}
